package tesoreria.compras.ordencompra.infrastructure.web.mapper;
import org.springframework.stereotype.Component; import tesoreria.compras.ordencompra.domain.model.*; import tesoreria.compras.ordencompra.infrastructure.web.dto.*; import java.util.List;
@Component public class OrdenCompraDtoMapper { public List<OrdenCompraItem> toItems(List<OrdenCompraItemRequest> i){return i.stream().map(x->new OrdenCompraItem(x.articuloId(),x.descripcion(),x.cantidad(),x.precioUnitario(),x.imputacionId())).toList();} public OrdenCompraResponse toResponse(OrdenCompra o){return new OrdenCompraResponse(o.id(),o.numero(),o.fechaEmision(),o.proveedorId(),o.sedeId(),o.observaciones(),o.estado().name(),o.total(),o.items().stream().map(i->new OrdenCompraItemResponse(i.articuloId(),i.descripcion(),i.cantidad(),i.precioUnitario(),i.imputacionId(),i.subtotal())).toList());} }
